'use client';

import { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion'; // برای انیمیشن‌ها
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

// ایمپورت آیکون‌ها
import { 
  ArrowRight, MapPin, Calendar, Bus, 
  CheckCircle2, Armchair, AlertCircle, Loader2, SteeringWheel, Ticket, Info 
} from 'lucide-react';

// کامپوننت‌های فرضی (اگر ندارید از کد استاندارد پایین استفاده کنید)
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';

// --- ابزار کمکی برای کلاس‌ها ---
function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// --- تعریف تایپ‌ها ---
interface Seat {
  id: number;
  seat_number: number;
  is_reserved: boolean;
  reserved_by?: { first_name: string; last_name: string };
}

interface TripDetails {
  id: number;
  route: {
    origin: string;
    destination: string;
    company: string;
    distance_km: number;
    estimated_duration: string;
  };
  fleet: {
    license_plate: string;
    model: string;
    brand: string;
    capacity: number;
    bus_type: "standard" | "vip" | "luxury";
    facilities: string[];
  };
  departure_datetime: string;
  arrival_datetime: string;
  current_price: string;
  status: string;
  driver_name: number;
  driver_phone: string;
}

// --- کامپوننت کوچک بلیط تکی (Ticket Item) ---
const TicketItem = ({ seatNumber, price, onRemove }: { seatNumber: number, price: string, onRemove: () => void }) => (
  <motion.div 
    initial={{ opacity: 0, x: -20 }}
    animate={{ opacity: 1, x: 0 }}
    exit={{ opacity: 0, scale: 0.8 }}
    className="relative bg-white border border-blue-100 rounded-lg shadow-sm overflow-hidden mb-3 group"
  >
    {/* افکت سوراخ‌های بلیط */}
    <div className="absolute top-1/2 -right-2 w-4 h-4 bg-gray-50 rounded-full border border-blue-100" />
    <div className="absolute top-1/2 -left-2 w-4 h-4 bg-gray-50 rounded-full border border-blue-100" />
    <div className="absolute top-1/2 left-2 right-2 border-t-2 border-dashed border-blue-100 opacity-50" />

    <div className="p-3 flex justify-between items-center relative z-10">
      <div className="flex flex-col">
        <span className="text-xs text-blue-400 font-bold uppercase tracking-wider">بلیط مسافر</span>
        <span className="text-lg font-black text-blue-900">صندلی {seatNumber}</span>
      </div>
      <div className="text-left">
        <span className="block text-sm font-bold text-gray-700">{price}</span>
        <span className="text-[10px] text-gray-400">تومان</span>
      </div>
    </div>
    <div 
      onClick={onRemove}
      className="absolute inset-0 bg-red-500/10 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer flex items-center justify-center text-red-600 font-bold text-sm backdrop-blur-[1px]"
    >
      حذف بلیط
    </div>
  </motion.div>
);

export default function BookingPage() {
  const params = useParams();
  const router = useRouter();
  const tripId = params.tripId as string;

  // --- استیت‌ها ---
  const [seats, setSeats] = useState<Seat[]>([]);
  const [tripDetails, setTripDetails] = useState<TripDetails | null>(null);
  const [selectedSeats, setSelectedSeats] = useState<number[]>([]);
  const [loading, setLoading] = useState(true);
  const [reserving, setReserving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // --- توابع کمکی ---
  const formatPrice = (price: string | number) => Number(price).toLocaleString('fa-IR');
  
  const formatDateTime = (dateString: string) => {
    const date = new Date(dateString);
    return {
      time: date.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', hour12: false }),
      date: date.toLocaleDateString('fa-IR', { month: 'long', day: 'numeric' }),
      weekday: date.toLocaleDateString('fa-IR', { weekday: 'long' })
    };
  };

  // --- دریافت اطلاعات ---
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const tripRes = await fetch(`/trips/api/v1/trips/${tripId}/`);
        if (!tripRes.ok) throw new Error('خطا در دریافت اطلاعات سفر');
        const tripData = await tripRes.json();
        setTripDetails(tripData);

        const token = localStorage.getItem('accessToken');
        const seatRes = await fetch(`/seat/api/v1/api/seats/trip/${tripId}/`, {
          headers: token ? { 'Authorization': `Bearer ${token}` } : {}
        });
        if (!seatRes.ok) throw new Error('خطا در دریافت لیست صندلی‌ها');
        const seatData = await seatRes.json();
        setSeats(seatData.seats || []); 
        
      } catch (err) {
        console.error(err);
        setError('مشکلی در ارتباط با سرور پیش آمده است.');
      } finally {
        setLoading(false);
      }
    };
    if (tripId) fetchData();
  }, [tripId]);

  // --- مدیریت انتخاب صندلی ---
  const toggleSeat = (seatId: number, isReserved: boolean) => {
    if (isReserved) return;
    setSelectedSeats(prev => {
      if (prev.includes(seatId)) return prev.filter(id => id !== seatId);
      if (prev.length >= 4) {
        alert("حداکثر ۴ صندلی می‌توانید انتخاب کنید.");
        return prev;
      }
      return [...prev, seatId];
    });
  };

  const handleReservation = async () => {
    if (selectedSeats.length === 0) return;
    setReserving(true);
    const token = localStorage.getItem("accessToken");

    try {
      // 1. ایجاد رزرو
      const createRes = await fetch("/reservations/api/v1/api/reservations/", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${token}` },
        body: JSON.stringify({ seat: selectedSeats[0] }), // نکته: فقط صندلی اول در این دمو رزرو می‌شود
      });
      const reservation = await createRes.json();
      if (!createRes.ok) throw new Error(reservation.detail || "خطا در رزرو");

      // 2. تایید پرداخت
      const payRes = await fetch(
        `/reservations/api/v1/api/reservations/${reservation.id}/confirm_payment/`,
        { method: "POST", headers: { "Authorization": `Bearer ${token}` } }
      );
      if (!payRes.ok) throw new Error("خطا در تایید پرداخت");

      router.push("/dashboard/tickets");
    } catch (err: any) {
      setError(err.message);
    } finally {
      setReserving(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-blue-50 gap-4">
        <div className="relative">
          <div className="absolute inset-0 bg-blue-400 rounded-full blur-xl opacity-20 animate-pulse"></div>
          <Bus className="w-16 h-16 text-blue-600 animate-bounce" />
        </div>
        <p className="text-blue-800 font-bold text-lg">در حال آماده‌سازی اتوبوس...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F0F4FF] font-sans pb-20 selection:bg-blue-200" dir="rtl">
      
      {/* --- هدر مدرن --- */}
      <div className="bg-white/80 backdrop-blur-md sticky top-0 z-20 border-b border-blue-100 shadow-sm">
        <div className="container mx-auto max-w-6xl px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="icon" className="rounded-full hover:bg-blue-50 text-blue-600" onClick={() => router.back()}>
              <ArrowRight className="w-5 h-5" />
            </Button>
            <h1 className="font-black text-xl text-slate-800 tracking-tight">انتخاب صندلی</h1>
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100">
             <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
             <span className="text-xs font-bold text-blue-700">اتصال برقرار</span>
          </div>
        </div>
      </div>

      <main className="container mx-auto px-4 py-8 max-w-6xl space-y-8">
        
        {error && (
          <Alert variant="destructive" className="bg-red-50 border-red-200 text-red-700 rounded-xl shadow-sm">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="font-medium">{error}</AlertDescription>
          </Alert>
        )}

        {/* --- کارت اطلاعات سفر (شیشه‌ای و جذاب) --- */}
        {tripDetails && (
          <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-3xl p-6 shadow-xl shadow-blue-200 text-white relative overflow-hidden">
             {/* پس‌زمینه تزئینی */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl"></div>
            <div className="absolute bottom-0 left-0 w-40 h-40 bg-blue-300 opacity-10 rounded-full translate-y-1/2 -translate-x-1/2 blur-2xl"></div>

            <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
              {/* مبدا و مقصد */}
              <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-start">
                <div className="text-center">
                  <p className="text-blue-100 text-sm mb-1">مبدا حرکت</p>
                  <h2 className="text-2xl font-black">{tripDetails.route.origin}</h2>
                  <p className="text-2xl font-bold opacity-90">{formatDateTime(tripDetails.departure_datetime).time}</p>
                </div>
                
                <div className="flex-1 md:w-48 flex flex-col items-center gap-1">
                   <span className="text-xs text-blue-200 bg-white/10 px-2 py-0.5 rounded-full">{tripDetails.route.estimated_duration}</span>
                   <div className="w-full h-1 bg-white/20 rounded-full relative flex items-center">
                      <div className="w-2 h-2 bg-white rounded-full absolute right-0"></div>
                      <Bus className="w-6 h-6 text-white absolute left-1/2 -translate-x-1/2 -mt-3 bg-indigo-700 rounded p-0.5" />
                      <div className="w-2 h-2 bg-white/50 rounded-full absolute left-0"></div>
                   </div>
                   <span className="text-[10px] text-blue-200">{tripDetails.route.distance_km} کیلومتر</span>
                </div>

                <div className="text-center">
                  <p className="text-blue-100 text-sm mb-1">مقصد</p>
                  <h2 className="text-2xl font-black">{tripDetails.route.destination}</h2>
                  <p className="text-lg font-medium opacity-70">{formatDateTime(tripDetails.arrival_datetime).time}</p>
                </div>
              </div>

              <div className="bg-white/10 backdrop-blur-sm p-4 rounded-2xl flex items-center gap-4 border border-white/10">
                <div className="bg-white p-2 rounded-xl text-blue-600">
                  <Bus className="w-6 h-6" />
                </div>
                <div>
                  <p className="font-bold text-lg">{tripDetails.route.company}</p>
                  <div className="flex items-center gap-2 text-sm text-blue-200">
                    <span className="bg-orange-400/20 text-orange-100 px-2 py-0.5 rounded text-xs border border-orange-400/30">
                      {tripDetails.fleet.bus_type === 'vip' ? 'VIP تخت‌شو' : 'معمولی'}
                    </span>
                    <span>{tripDetails.fleet.model}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          
          {/* --- ستون راست: نقشه گرافیکی اتوبوس (8 واحد) --- */}
          <div className="lg:col-span-8">
            <div className="bg-white rounded-[2.5rem] shadow-xl border-4 border-white ring-1 ring-gray-100 p-8 relative overflow-hidden">
               {/* عنوان گرافیکی */}
              <div className="flex items-center justify-between mb-10">
                <h3 className="flex items-center gap-2 font-bold text-slate-700">
                  <Armchair className="text-blue-500" />
                  نقشه صندلی‌ها
                </h3>
                <div className="flex gap-4 text-xs font-medium bg-gray-50 p-2 rounded-lg border border-gray-100">
                  <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-white border border-gray-300 rounded shadow-sm"></span>خالی</div>
                  <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-blue-600 rounded shadow-sm shadow-blue-300"></span>انتخابی</div>
                  <div className="flex items-center gap-1.5"><span className="w-3 h-3 bg-slate-200 rounded"></span>رزرو</div>
                </div>
              </div>

              {/* بدنه اتوبوس */}
              <div className="mx-auto max-w-[380px] bg-slate-50 border-x-8 border-slate-200 rounded-t-[3rem] rounded-b-3xl relative pb-12 pt-20 px-6 shadow-inner">
                
                {/* قسمت راننده */}
                <div className="absolute top-8 right-8 bg-slate-200 p-2 rounded-xl text-slate-400">
                   <SteeringWheel className="w-8 h-8" />
                </div>
                <div className="absolute top-6 left-1/2 -translate-x-1/2 text-slate-300 text-xs font-bold tracking-[0.2em] uppercase">
                  جلوی اتوبوس
                </div>
                <div className="absolute top-20 left-8 border-l-4 border-dashed border-slate-300 h-10 w-4"></div> {/* درب */}

                {/* گرید صندلی‌ها */}
                <div className="grid grid-cols-4 gap-x-4 gap-y-5" dir="ltr">
                  {seats.map((seat) => {
                    const isSelected = selectedSeats.includes(seat.id);
                    const isReserved = seat.is_reserved;

                    return (
                      <motion.button
                        key={seat.id}
                        whileHover={!isReserved ? { scale: 1.05, y: -2 } : {}}
                        whileTap={!isReserved ? { scale: 0.95 } : {}}
                        onClick={() => toggleSeat(seat.id, isReserved)}
                        disabled={isReserved}
                        className={cn(
                          "relative h-14 rounded-xl flex items-center justify-center font-bold text-sm transition-all duration-200 border-b-[3px] shadow-sm",
                          // استایل صندلی رزرو شده
                          isReserved && "bg-slate-200 text-slate-400 border-slate-300 cursor-not-allowed",
                          // استایل صندلی انتخاب شده
                          isSelected && "bg-blue-600 text-white border-blue-800 shadow-blue-300 shadow-lg z-10",
                          // استایل صندلی خالی
                          !isReserved && !isSelected && "bg-white text-slate-600 border-slate-200 hover:border-blue-300 hover:shadow-md hover:text-blue-600"
                        )}
                      >
                        {/* جزئیات گرافیکی صندلی */}
                        <div className="absolute -top-2 w-4/5 h-2 rounded-t-full bg-inherit opacity-80 border-t border-inherit"></div>
                        
                        {seat.seat_number}

                        {isSelected && (
                          <motion.div 
                            initial={{ scale: 0 }} animate={{ scale: 1 }}
                            className="absolute -top-2 -right-2 bg-green-500 rounded-full p-0.5 border-2 border-white shadow-sm"
                          >
                            <CheckCircle2 className="w-3 h-3 text-white" />
                          </motion.div>
                        )}
                      </motion.button>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>

          {/* --- ستون چپ: پنل بلیط و پرداخت (4 واحد) --- */}
          <div className="lg:col-span-4 space-y-4 sticky top-24">
            
            {/* کارت سفید برای جزئیات */}
            <div className="bg-white rounded-2xl shadow-xl shadow-blue-100/50 border border-blue-50 overflow-hidden">
              <div className="bg-slate-900 px-6 py-4 flex items-center justify-between">
                <span className="text-white font-bold flex items-center gap-2">
                  <Ticket className="w-5 h-5 text-blue-400" />
                  سبد خرید
                </span>
                <Badge variant="secondary" className="bg-white/10 text-white hover:bg-white/20 border-0">
                  {selectedSeats.length} صندلی
                </Badge>
              </div>

              <div className="p-5 bg-slate-50 min-h-[150px]">
                <AnimatePresence>
                  {selectedSeats.length > 0 ? (
                    seats
                      .filter(s => selectedSeats.includes(s.id))
                      .map(s => (
                        <TicketItem 
                          key={s.id} 
                          seatNumber={s.seat_number} 
                          price={tripDetails ? formatPrice(tripDetails.current_price) : '0'} 
                          onRemove={() => toggleSeat(s.id, false)}
                        />
                      ))
                  ) : (
                    <div className="flex flex-col items-center justify-center h-40 text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
                      <Armchair className="w-10 h-10 mb-2 opacity-50" />
                      <span className="text-sm">هنوز صندلی انتخاب نکرده‌اید</span>
                    </div>
                  )}
                </AnimatePresence>
              </div>

              {/* بخش جمع کل */}
              <div className="p-6 bg-white border-t border-gray-100">
                <div className="flex justify-between items-end mb-6">
                  <span className="text-gray-500 font-medium text-sm">مبلغ قابل پرداخت:</span>
                  <div className="text-left">
                    <span className="block text-2xl font-black text-slate-800">
                      {tripDetails ? formatPrice(selectedSeats.length * Number(tripDetails.current_price)) : 0}
                    </span>
                    <span className="text-xs text-gray-400 font-bold">تومان / آنلاین</span>
                  </div>
                </div>

                <Button 
                  className="w-full h-14 text-lg font-bold bg-blue-600 hover:bg-blue-500 shadow-lg shadow-blue-200 hover:shadow-blue-300 transition-all rounded-xl"
                  onClick={handleReservation}
                  disabled={reserving || selectedSeats.length === 0}
                >
                  {reserving ? (
                    <>
                      <Loader2 className="w-5 h-5 ml-2 animate-spin" />
                      در حال صدور...
                    </>
                  ) : (
                    <span className="flex items-center gap-2">
                      تایید نهایی و پرداخت
                      <ArrowRight className="w-5 h-5" />
                    </span>
                  )}
                </Button>
                
                <div className="mt-4 flex gap-2 text-[10px] text-gray-400 bg-gray-50 p-2 rounded border border-gray-100">
                  <Info className="w-3 h-3 shrink-0 mt-0.5" />
                  <p>استرداد بلیط تا ۱ ساعت قبل از حرکت با ۱۰٪ جریمه امکان‌پذیر است.</p>
                </div>
              </div>
            </div>

            {/* کارت پشتیبانی کوچک */}
            <div className="bg-blue-600 rounded-2xl p-4 text-white flex items-center gap-4 shadow-lg shadow-blue-200">
              <div className="bg-white/20 p-2 rounded-full">
                <Calendar className="w-5 h-5" />
              </div>
              <div>
                <p className="text-xs text-blue-100 mb-0.5">تاریخ حرکت</p>
                <p className="font-bold text-sm">
                  {tripDetails ? formatDateTime(tripDetails.departure_datetime).weekday : '...'}، {tripDetails ? formatDateTime(tripDetails.departure_datetime).date : '...'}
                </p>
              </div>
            </div>

          </div>
        </div>
      </main>
    </div>
  );
}